                new("Why is a job like baker easier to remember than a name?", ["It is a shorter word", "The word connects to other things in our brain", "We hear it more often", "It is easier to pronounce"], 1, "The host says the brain \"connects that word to bread, smells and early mornings\"."),
                new("What is the final piece of advice?", ["Write the name down", "Ask for a business card", "Repeat the name silently many times", "Use the name once more before saying goodbye"], 3, "The host says, \"Use it once more before you say goodbye.\""),
            ])),
